/**
 * API reference: which API is published in which documentation.
 *
 * The pages of each API are generated from its spec (openapi/) by
 * `pnpm gen-api` in <docs>/api/reference/<api>/, inside the OnPrem docs of a
 * version or the Cloud docs, and are listed in the API category of their
 * sidebar (an "autogenerated" item, see apiSidebarItemsGenerator below).
 *
 * Read by docusaurus.config.js (plugin docusaurus-plugin-openapi-docs and
 * sidebars) and by generate.mjs.
 */
import fs from 'node:fs';
import path from 'node:path';

export const REFERENCE_DIR = 'api/reference';

// How each API is introduced: its name on its endpoint pages (badge), the
// "Get started" page (template in intros/, which replaces the description of
// the spec), and the security scheme of its API token.
export const APIS = {
  web: {
    title: 'Centreon Web REST API',
    badge: 'Centreon Web',
    auth: 'Token',
    template: 'centreon-web.mdx',
    description: (target) =>
      `Centreon Web REST API ${target.version}: get a token, make your first request, and browse every endpoint with its parameters, schemas and code samples.`,
  },
  cloud: {
    title: 'Centreon Cloud REST API',
    badge: 'Centreon Cloud',
    auth: 'Token',
    template: 'centreon-cloud.mdx',
    description: () =>
      'Centreon Cloud REST API: get an API token, make your first request, and browse the configuration endpoints with their schemas and code samples.',
  },
  map: {
    title: 'Centreon MAP REST API',
    badge: 'Centreon MAP',
    auth: 'CentreonHeaderAuth',
    template: 'centreon-map.mdx',
    description: () =>
      'Centreon MAP REST API: sign in, make your first request, and browse the endpoints for maps, views and access rights, with code samples.',
  },
  bam: {
    title: 'Centreon BAM REST API',
    badge: 'Centreon BAM',
    auth: 'Token',
    template: 'centreon-bam.mdx',
    description: () =>
      'Centreon BAM REST API: get a token, make your first request, and browse the endpoints for business views, business activities and indicators.',
  },
};

// Documentations that publish an API reference, with the spec of each API.
// `dir` is the API's directory under api/reference/, which the sidebar of the
// documentation points to ("dirName" of an autogenerated item). `values` fill
// the {{placeholders}} of the intro template.
export const TARGETS = [
  {
    docs: 'versioned_docs/version-24.10',
    version: '24.10',
    values: { baseUrl: 'https://<your-centreon-server>/centreon', tokensDoc: '../../api-tokens.md', postmanDoc: '../../rest-api-v2.md' },
    apis: [{ api: 'web', dir: 'web', spec: 'centreon-web-24.10.json' }],
  },
  {
    docs: 'versioned_docs/version-25.10',
    version: '25.10',
    values: { baseUrl: 'https://<your-centreon-server>/centreon', tokensDoc: '../../api-tokens.md', postmanDoc: '../../rest-api-v2.md' },
    apis: [{ api: 'web', dir: 'web', spec: 'centreon-web-25.10.json' }],
  },
  {
    docs: 'versioned_docs/version-26.10',
    version: '26.10',
    values: { baseUrl: 'https://<your-centreon-server>/centreon', tokensDoc: '../../authentication-tokens.md', postmanDoc: '../../rest-api-v2.md', mapDoc: '../../map-api.md' },
    apis: [
      { api: 'web', dir: 'web', spec: 'centreon-web-26.10.json' },
      { api: 'map', dir: 'map', spec: 'centreon-map-26.10.json' },
      { api: 'bam', dir: 'bam', spec: 'centreon-bam-26.10.json' },
    ],
  },
  {
    // No spec of 27.10 yet: same APIs as 26.10.
    docs: 'versioned_docs/version-27.10',
    version: '27.10',
    values: { baseUrl: 'https://<your-centreon-server>/centreon', tokensDoc: '../../authentication-tokens.md', postmanDoc: '../../rest-api-v2.md', mapDoc: '../../map-api.md' },
    apis: [
      { api: 'web', dir: 'web', spec: 'centreon-web-26.10.json' },
      { api: 'map', dir: 'map', spec: 'centreon-map-26.10.json' },
      { api: 'bam', dir: 'bam', spec: 'centreon-bam-26.10.json' },
    ],
  },
  {
    docs: 'cloud',
    version: 'cloud',
    values: { baseUrl: 'https://<organization>.<region>.centreon.cloud/<instance-name>', tokensDoc: '../../../administration/api-tokens.md' },
    apis: [
      { api: 'cloud', dir: 'web', spec: 'centreon-web-cloud.json' },
      { api: 'map', dir: 'map', spec: 'centreon-map-26.10.json' },
      { api: 'bam', dir: 'bam', spec: 'centreon-bam-cloud.json' },
    ],
  },
];

// Documentations of the build: OnPrem versions built, and Cloud if built.
export function targetsOf({ versions, cloud }) {
  return TARGETS.filter((target) => (target.docs === 'cloud' ? cloud : versions.includes(target.version)));
}

// Entries of docusaurus-plugin-openapi-docs: one per documentation and API.
export function openapiConfig(targets) {
  return Object.fromEntries(
    targets.flatMap((target) =>
      target.apis.map(({ api, dir, spec }) => [
        `${target.version.replace('.', '')}-${dir}`,
        {
          specPath: `openapi/${spec}`,
          outputDir: `${target.docs}/${REFERENCE_DIR}/${dir}`,
          sidebarOptions: { groupPathsBy: 'tag' },
        },
      ]),
    ),
  );
}

// Sidebar items of an API reference: sidebar.json, written by generate.mjs
// next to the pages. When the pages are not generated (API=0), a link to the
// former reference on docs-api.centreon.com instead, so that the sidebar is
// still valid.
const FALLBACK_URLS = {
  web: 'https://docs-api.centreon.com/api/centreon-web/',
  map: 'https://docs-api.centreon.com/api/centreon-map/',
  bam: 'https://docs-api.centreon.com/api/centreon-bam/',
};

export async function apiSidebarItemsGenerator({ defaultSidebarItemsGenerator, ...args }) {
  const { item, version } = args;
  if (!item.dirName.startsWith(`${REFERENCE_DIR}/`)) {
    return defaultSidebarItemsGenerator(args);
  }
  const file = path.join(version.contentPath, item.dirName, 'sidebar.json');
  if (fs.existsSync(file)) {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  }
  const dir = path.basename(item.dirName);
  return [{ type: 'link', label: 'API reference', href: FALLBACK_URLS[dir] ?? 'https://docs-api.centreon.com/' }];
}
